import random
import string
from typing import List

# Data type: command-line argument string
# We need to generate a bytes buffer that the fuzzing harness will slice into
# multiple C-strings (via FUZZ_PARAM_STR / FUZZ_PARAM_FILENAME). The target
# stubs primarily consume argv-like strings for WASI args (dirs, map-dirs,
# env, argv) and function names. Provide a buffer that contains several
# NUL-terminated strings covering interesting cases and formats:
# - normal short args
# - long args near limits
# - flags (-h, --help, -I=/path)
# - paths (relative, absolute, Windows-like)
# - map-dir entries in the form "guest::host"
# - env vars in the form "KEY=VALUE"
# - utf-8 and spaces, quotes
# - empty string
# Ensure the total size <= 4096 bytes.

SEP = b"\x00"
MAX_TOTAL = 4096

WORDS = [
    "main", "run", "test", "exec", "calc", "fib", "wasm", "module",
    "αβγ", "日本語", "with space", "quoted\"arg", "newline\ninside",
    "--help", "-h", "-v", "--verbose", "--version",
    "--flag", "-O3", "--opt", "--threads=4",
]

ENV_KEYS = [
    "PATH", "HOME", "USER", "LANG", "RUST_LOG", "LOG_LEVEL", "WASM_LOG",
    "TMPDIR", "SHELL", "TERM",
]

DIR_GUESTS = [
    "/", "/tmp", "/sandbox", "/work", "/data", "/mnt/in", "/mnt/out",
    "/proc", "/dev", "/home/user",
]

DIR_HOSTS = [
    ".", "./tmp", "/tmp", "/var/tmp", "/home/fuzzer", "C:/host/tmp",
]

PATHS = [
    ".", "..", "./a", "a/b", "/abs/path", "/tmp/file.txt",
    "C:/Windows/System32", "\\\\server\\share",
]

FUNCS = [
    "_start", "main", "_initialize", "entry", "_Z3foov", "wasm_call",
    "$mod$func", "add", "multiply", "memory_grow", "env$func",
]

FLAGS = [
    "--", "-", "-Iinclude", "-L/usr/lib", "--dir=/tmp",
]


def _rand_utf8(r: random.Random, min_len: int = 0, max_len: int = 24) -> str:
    # Mix ASCII and some extended codepoints
    length = r.randint(min_len, max_len)
    choices = (
        list(string.ascii_letters + string.digits + "-_./:=@" + " ")
        + ["α", "β", "γ", "漢", "字", "é", "ü", "ñ", "•"]
    )
    return "".join(r.choice(choices) for _ in range(length))


def _env_entry(r: random.Random) -> str:
    key = r.choice(ENV_KEYS + [
        _rand_utf8(r, 1, 8).replace("=", "_")
    ])
    val = r.choice(WORDS) + r.choice(["", ":/usr/bin", ":/bin", ":/custom"]) + _rand_utf8(r, 0, 8)
    return f"{key}={val}"


def _map_dir_entry(r: random.Random) -> str:
    guest = r.choice(DIR_GUESTS + ["/app", "/root", "/sandbox/data"]) + _rand_utf8(r, 0, 6)
    host = r.choice(DIR_HOSTS + PATHS) + _rand_utf8(r, 0, 6)
    # Ensure format guest::host
    return f"{guest}::{host}"


def _path_arg(r: random.Random) -> str:
    base = r.choice(PATHS + DIR_HOSTS)
    ext = r.choice(["", ".wasm", ".wat", ".txt", ".bin"])
    return base + ext


def _argv_entry(r: random.Random) -> str:
    pick = r.randint(0, 8)
    if pick == 0:
        return r.choice(FLAGS)
    if pick == 1:
        return r.choice(WORDS)
    if pick == 2:
        return _path_arg(r)
    if pick == 3:
        return "-D" + _rand_utf8(r, 1, 8)
    if pick == 4:
        return "--set=" + _rand_utf8(r, 1, 6)
    if pick == 5:
        return "-n=" + str(r.randint(0, 10000))
    if pick == 6:
        return "--map=" + _map_dir_entry(r)
    if pick == 7:
        return "--env=" + _env_entry(r)
    return _rand_utf8(r, 0, 16)


def _func_name(r: random.Random) -> str:
    # Limit to 32 chars as stub truncates names > 32
    s = r.choice(FUNCS + [
        _rand_utf8(r, 1, 20),
        "mod$" + _rand_utf8(r, 1, 10),
        "_Z" + str(r.randint(1, 999)) + _rand_utf8(r, 1, 8),
    ])
    return s[:32]


def _make_cstr(s: str) -> bytes:
    # Ensure no embedded NULs; replace if any
    s = s.replace("\x00", " ")
    return s.encode('utf-8', errors='ignore') + b"\x00"


def _assemble(strings: List[str]) -> bytes:
    out = b"".join(_make_cstr(s) for s in strings)
    # Ensure final NUL terminator to avoid reading past end
    if not out.endswith(b"\x00"):
        out += b"\x00"
    return out[:MAX_TOTAL]


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    strings: List[str] = []

    # Provide several categories that the stubs may pull from in arbitrary order.
    # 1) Function names for wasm_application_execute_func
    for _ in range(r.randint(2, 6)):
        strings.append(_func_name(r))

    # 2) Argv for execute_main and instantiation args
    for _ in range(r.randint(4, 16)):
        strings.append(_argv_entry(r))

    # 3) Env entries
    for _ in range(r.randint(2, 8)):
        strings.append(_env_entry(r))

    # 4) Map dir entries "guest::host"
    for _ in range(r.randint(2, 6)):
        strings.append(_map_dir_entry(r))

    # 5) Plain dir paths
    for _ in range(r.randint(2, 6)):
        strings.append(_path_arg(r))

    # 6) Include some edge cases
    strings.extend([
        "",  # empty string
        " ",  # single space
        "--",  # end-of-options marker
        "-",   # lone dash
        "--dir=/", "--dir=./tmp",
        "--env=EMPTY=",  # env with empty value
        "guest::host",   # minimal map-dir pattern
        "/very/long/path/" + _rand_utf8(r, 50, 120),
    ])

    # 7) A very long function name (will be truncated by stub)
    strings.append(_func_name(r) + _rand_utf8(r, 16, 64))

    buf = _assemble(strings)

    # Respect size limit; if too large, trim by dropping tail strings
    while len(buf) > MAX_TOTAL:
        # Remove a few tail entries and rebuild
        if strings:
            strings.pop()
        else:
            break
        buf = _assemble(strings)

    return buf

import random
