from typing import List

# Target data type: arbitrary binary data
# Used by fuzzer stub: wasm_runtime_module_dup_data via FUZZ_PARAM_STR()
# Produce interesting, valid byte buffers (<= 4096 bytes), deterministic per seed.

_MAX_SIZE = 4096

def _rand(r: random.Random, a: int, b: int) -> int:
    return r.randint(a, b)

def _weighted_choice(r: random.Random, items: List):
    # items: list of (value, weight)
    total = sum(w for _, w in items)
    pick = r.uniform(0, total)
    acc = 0.0
    for v, w in items:
        acc += w
        if pick <= acc:
            return v
    return items[-1][0]

def _gen_sizes(r: random.Random) -> int:
    # Prefer small/medium sizes but sometimes large and boundary sizes.
    size_kinds = [
        ("tiny", 25), ("small", 30), ("medium", 25), ("large", 12), ("xl", 6), ("edge", 2)
    ]
    kind = _weighted_choice(r, size_kinds)
    if kind == "tiny":
        return _rand(r, 1, 16)
    if kind == "small":
        return _rand(r, 17, 128)
    if kind == "medium":
        return _rand(r, 129, 1024)
    if kind == "large":
        return _rand(r, 1025, 2048)
    if kind == "xl":
        return _rand(r, 2049, _MAX_SIZE)
    # edge cases including powers of two and special values
    candidates = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 767, 768, 1023, 1024, 1536, 2048, 3072, 4096]
    sz = r.choice(candidates)
    if sz == 0:
        sz = 1
    return min(sz, _MAX_SIZE)

def _pattern_repeat(byte: int, size: int) -> bytes:
    return bytes([byte]) * size

def _pattern_incrementing(size: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF for i in range(size)))

def _pattern_decrementing(size: int, start: int = 255) -> bytes:
    return bytes(((start - i) & 0xFF for i in range(size)))

def _pattern_words(r: random.Random, size: int, w: int) -> bytes:
    # Emit patterns of w-byte words with various interesting values
    out = bytearray()
    packers = {1: "B", 2: "<H", 4: "<I", 8: "<Q"}
    vals8 = [0x00, 0xFF]
    vals16 = [0x0000, 0x00FF, 0xFF00, 0xFFFF]
    vals32 = [0x00000000, 0x000000FF, 0x0000FF00, 0x00FF0000, 0xFF000000, 0xFFFFFFFF]
    vals64 = [0x0, 0xFF, 0xFFFF, 0xFFFFFFFF, 0xFFFFFFFFFFFFFFFF]
    if w == 1:
        pool = vals8
    elif w == 2:
        pool = vals16
    elif w == 4:
        pool = vals32
    else:
        pool = vals64
    while len(out) + w <= size:
        v = r.choice(pool)
        out += struct.pack(packers[w], v)
