def _pattern_wasm_like(r: random.Random, size: int) -> bytes:
    # Emit a buffer that starts like a valid WebAssembly binary
    out = bytearray()
    out += b"\x00asm"  # magic
    out += b"\x01\x00\x00\x00"  # version 1
    while len(out) < size:
        out.append(r.randrange(256))
    return bytes(out[:size])

def _pattern_sparse(r: random.Random, size: int) -> bytes:
    # Mostly zeros with random islands
    out = bytearray(size)
    if size == 0:
        return bytes(out)
    islands = max(1, size // max(1, _rand(r, 32, 256)))
    for _ in range(islands):
        pos = _rand(r, 0, size - 1)
        span = min(size - pos, _rand(r, 1, min(32, size - pos) if size - pos > 0 else 1))
        for i in range(span):
            out[pos + i] = r.randrange(256)
    return bytes(out)

def _pattern_structured(r: random.Random, size: int) -> bytes:
    # Mix of length-prefixed chunks, zeros, and counters
    out = bytearray()
    counter = r.randrange(0, 2**32)
    while len(out) + 8 <= size:
        chunk_len = r.randint(0, min(64, size - len(out) - 8))
        out += struct.pack("<I", chunk_len)
        out += struct.pack("<I", counter & 0xFFFFFFFF)
        counter = (counter + r.randint(1, 1000)) & 0xFFFFFFFF
        for _ in range(chunk_len):
            if len(out) >= size:
                break
            out.append(r.randrange(256))
    while len(out) < size:
        out.append(0)
    return bytes(out[:size])

def _pattern_random(r: random.Random, size: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(size))

def _compose_patterns(r: random.Random, size: int) -> bytes:
    if size <= 1:
        # Degenerate: just random single byte (or empty, but caller ensures >=1)
        return _pattern_random(r, size)
    # Split size into 2-4 segments but ensure population >= k for sampling
    max_segments = min(4, size)  # can't have more segments than bytes
    segments = r.randint(2, max_segments)
    # We need segments-1 cut points from positions 1..size-1 (population size = size-1)
    population = size - 1
    k = min(segments - 1, population)
    if k <= 0:
        cuts = []
    else:
        # random.sample requires a sequence; use range(1, size)
        cuts = sorted(r.sample(range(1, size), k))
    parts = []
    last = 0
    for c in cuts + [size]:
        parts.append(c - last)
        last = c
    gens = [
        lambda n: _pattern_repeat(r.randrange(256), n),
        lambda n: _pattern_incrementing(n, r.randrange(256)),
        lambda n: _pattern_decrementing(n, r.randrange(256)),
        lambda n: _pattern_words(r, n, r.choice([1, 2, 4, 8]) if n >= 1 else 1),
        lambda n: _pattern_sparse(r, n),
        lambda n: _pattern_random(r, n),
    ]
    out = bytearray()
    for n in parts:
        if n <= 0:
            continue
        gen = r.choice(gens)
        out += gen(n)
    # Safety: pad/trim to exact size
    if len(out) < size:
        out += _pattern_random(r, size - len(out))
    return bytes(out[:size])

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    size = _gen_sizes(r)

    patterns = [
        (lambda: _pattern_repeat(0x00, size), 2),
        (lambda: _pattern_repeat(0xFF, size), 2),
        (lambda: _pattern_incrementing(size, r.randrange(256)), 4),
        (lambda: _pattern_decrementing(size, r.randrange(256)), 3),
        (lambda: _pattern_words(r, size, 1), 2),
        (lambda: _pattern_words(r, size, 2), 3),
        (lambda: _pattern_words(r, size, 4), 3),
        (lambda: _pattern_words(r, size, 8), 2),
        (lambda: _pattern_utf8(r, size), 3),
        (lambda: _pattern_wasm_like(r, size), 3),
        (lambda: _pattern_sparse(r, size), 3),
        (lambda: _pattern_structured(r, size), 3),
        (lambda: _pattern_random(r, size), 6),
        (lambda: _compose_patterns(r, size), 6),
    ]

    choice = _weighted_choice(r, patterns)
    data = choice()

    if not data:
        data = b"\x00"
    return data[:_MAX_SIZE]
